CREATE TABLE customers (
  id   BIGSERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT UNIQUE
);

CREATE TABLE orders (
  id BIGSERIAL PRIMARY KEY,
  customer_id BIGINT NOT NULL REFERENCES customers(id),   -- 없는 손님이면 거부
  amount INT NOT NULL CHECK (amount >= 0),                 -- 음수 금액 거부
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

BEGIN;
  UPDATE accounts SET balance = balance - 100 WHERE id = 1;
  UPDATE accounts SET balance = balance + 100 WHERE id = 2;
  -- 잔액이 음수가 되면 CHECK 제약이 여기서 막는다
COMMIT;

-- 읽고-계산하고-쓰기는 위험하다(경쟁). 한 문장으로 표현할 수 있으면 그렇게 하라
UPDATE accounts SET balance = balance - 100 WHERE id = 1 AND balance >= 100;

BEGIN;
  SELECT balance FROM accounts WHERE id = 1 FOR UPDATE;   -- 이 행을 잠근다
  -- 계산...
  UPDATE accounts SET balance = ... WHERE id = 1;
COMMIT;

-- 또는 아예 잠그지 않고 버전이 그대로면 쓰기 (낙관적)
UPDATE docs SET body = ?, version = version + 1
 WHERE id = ? AND version = ?;      -- 0행이 바뀌면 남이 먼저 고친 것 → 409

// 나쁨
const rows = await db.posts();
for (const p of rows) p.author = await db.user(p.user_id);   // N+1

// 좋음
const rows = await db.posts();
const ids = [...new Set(rows.map((p) => p.user_id))];
const users = await db.usersByIds(ids);                      // 한 번
const byId = new Map(users.map((u) => [u.id, u]));
for (const p of rows) p.author = byId.get(p.user_id);        // 앞 칸의 Map

-- 잠금을 오래 잡지 않게
CREATE INDEX CONCURRENTLY idx_orders_created ON orders (created_at);

-- 큰 UPDATE 는 나눠서
UPDATE orders SET full_name = name WHERE id BETWEEN 1 AND 10000;

